// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Attended flow engine: run queue, pause only when needed
// Flo: next pending item > approval gate > run job > done | park item (unsure, fail, skip) | needs-you: wait, resume same item | unsafe: stop flow, cooldown
// I/O: Sess + flow id + Env (caller) > Result (kind, counts, one-line fixes); item states saved before and after each act
// ===================================================================
const std = @import("std"); const sess = @import("ru-sess-ctxz.zig"); const flo = @import("st-flow-data.zig"); const appr = @import("ru-appr-list.zig"); const jobs = @import("ru-jobs-main.zig"); const halt = @import("ru-safe-halt.zig"); const wait = @import("ru-wait-hand.zig"); const noti = @import("ru-noti-send.zig");
const CF = .{ .hour = 3600000 };
pub const Env = struct { stat: []const u8 = "", real_toast: bool = false };
pub const Kind = enum { done, parked, blocked, unsafe, preview };
pub const Result = struct { kind: Kind = .done, done: u32 = 0, skip: u32 = 0, unsure: u32 = 0, fail: u32 = 0, lines: []const []const u8 = &.{} };
fn pending(itm: flo.Item) bool { return std.mem.eql(u8, itm.state, "todo") or std.mem.eql(u8, itm.state, "doing") or std.mem.eql(u8, itm.state, "wait"); }
fn modeFor(base: sess.Mode, itm: flo.Item) sess.Mode { if (base != .live and base != .force) return base; if (std.mem.eql(u8, itm.risk, "ask")) return .force; return .live; }
fn stopFlow(ses: *sess.Sess, env: Env, flow: i64, why: []const u8) !void { try flo.flowSet(ses.sto, flow, "stop"); try flo.metaPutInt(ses.sto, "cool_until", ses.now() + @as(i64, ses.cfg.cool_hour_coun) * CF.hour); const line = try noti.plain(ses.aren, why, "Flow stopped. Check Zalo by hand; after the cooldown run 'za-zalo-webs go' to continue at a calm pace."); _ = try noti.send(ses.aren, ses.iozz, ses.cfg, env.stat, line, ses.now(), env.real_toast); ses.logz("halt", why); }
pub fn run(ses: *sess.Sess, flow: i64, env: Env) !Result { var res: Result = .{}; var lines: std.ArrayList([]const u8) = .empty; const base = ses.mode; const preview = base == .dry or base == .read; if (!preview) { try flo.flowSet(ses.sto, flow, "run"); _ = try wait.recheck(ses); }
const plist = if (preview) try flo.itemsOf(ses.sto, ses.aren, flow) else &[0]flo.Item{}; var pidx: usize = 0; while (true) { var itm: flo.Item = undefined; if (preview) { while (pidx < plist.len and !pending(plist[pidx])) pidx += 1; if (pidx >= plist.len) break; itm = plist[pidx]; pidx += 1; } else { itm = (try flo.itemNext(ses.sto, ses.aren, flow)) orelse break; }
if (!itm.appr) { if (!preview) try flo.itemSet(ses.sto, itm.id, "skip", "not approved"); res.skip += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "item {d} skipped: not approved (run 'za-zalo-webs approve {d}')", .{ itm.id, itm.id })); if (preview) continue; continue; }
if (!preview) { if (itm.tries >= ses.cfg.retr_coun_maxz) { try flo.itemSet(ses.sto, itm.id, "fail", "too many tries"); res.fail += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "item {d} failed: too many tries", .{itm.id})); continue; } try flo.itemTry(ses.sto, itm.id); try flo.itemSet(ses.sto, itm.id, "doing", ""); }
ses.mode = modeFor(base, itm); ses.job = itm.job; const words = try appr.unpack(ses.aren, itm.args); const rep = jobs.dispatch(ses, itm.job, words) catch |err| { ses.mode = base; switch (err) {
error.NoElem, error.Ambiguous, error.BadJob => { if (!preview) try flo.itemSet(ses.sto, itm.id, "unsure", @errorName(err)); res.unsure += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "item {d} needs you: {s} ({s})", .{ itm.id, @errorName(err), itm.job })); continue; },
error.Fail, error.ChatFailed, error.AiFail => { if (!preview) try flo.itemSet(ses.sto, itm.id, "fail", @errorName(err)); res.fail += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "item {d} failed: {s}", .{ itm.id, @errorName(err) })); continue; },
error.NeedForce => { if (!preview) try flo.itemSet(ses.sto, itm.id, "skip", "needs approval to open a new chat"); res.skip += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "item {d} skipped: new recipient, run it by hand with --force", .{itm.id})); continue; },
error.QuietHrs, error.CapHit, error.UnknownModal => { if (!preview) { try flo.itemSet(ses.sto, itm.id, "todo", @errorName(err)); try flo.flowSet(ses.sto, flow, "pause"); } res.kind = .blocked; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "flow paused: {s}; run 'za-zalo-webs go' later", .{@errorName(err)})); res.lines = lines.items; return res; },
error.Halted, error.NeedLogin => { if (preview) { res.kind = .blocked; res.lines = lines.items; return res; } const cls: halt.Class = if (err == error.NeedLogin) .need else try halt.classOf(ses.sto, ses.aren); if (cls == .unsf) { try stopFlow(ses, env, flow, "Zalo showed a lock or warning"); res.kind = .unsafe; try lines.append(ses.aren, "flow stopped: unsafe page (lock or warning); cooldown 24 h"); res.lines = lines.items; return res; } try flo.itemSet(ses.sto, itm.id, "wait", @errorName(err)); const why = if (err == error.NeedLogin) "Zalo asks you to log in" else "Zalo shows a check for you"; const out = try wait.wait(ses, env.stat, why, env.real_toast); switch (out) { .cleared => { try flo.itemSet(ses.sto, itm.id, "todo", "resumed after owner"); continue; }, .deadline => { try flo.flowSet(ses.sto, flow, "wait"); res.kind = .parked; try lines.append(ses.aren, "flow parked: waited too long for you; open Zalo, handle it, then run 'za-zalo-webs go'"); res.lines = lines.items; return res; }, .unsafe => { try stopFlow(ses, env, flow, "Zalo checked the account again"); res.kind = .unsafe; try lines.append(ses.aren, "flow stopped: second check in 24 h; cooldown 24 h"); res.lines = lines.items; return res; } } },
else => return err } };
ses.mode = base; if (!preview) try flo.itemSet(ses.sto, itm.id, "done", ""); res.done += 1; for (rep.lines) |ln| try lines.append(ses.aren, ln); }
if (!preview) try flo.flowSet(ses.sto, flow, if (res.skip > 0) "partial" else "done"); res.kind = if (preview) .preview else .done; res.lines = lines.items; return res; }
